export const styleOf=p=>styles.find(s=>s.id===p.styleId)||styles.find(s=>s.name===p.style)||styles[0];
export const stageDefaults={idea:'Pertahankan naskah final persis. Rancang visual sesuai gaya terpilih, bahasa Indonesia natural. Akhir dan awal harus menyambung bila naskah menghendakinya.',story:'Bagi naskah pada jeda yang wajar. Setiap scene memiliki aksi konkret, fokus, kamera, kondisi awal/akhir dan aset yang diperlukan. Durasi sementara sampai VO tersedia.',voice:'Gunakan VO unggahan. Jangan mengganti kata. Timestamp berdasarkan rekaman, bukan pembagian waktu rata. Hasil yang meragukan harus ditinjau.',animation:'Ikuti naskah, visual dan timing aktif. Satu DUNIA bersama, scene dapat ditulis per kelompok. Semua posisi dihitung dari waktu. Periksa bentuk, kesinambungan dan margin aman.'};
export function ruleFor(p,key){let saved={};try{saved=JSON.parse(globalThis.localStorage?.getItem('ruang-stage-rules')||'{}');}catch{}return p.rules?.[key]??saved[key]??stageDefaults[key];}
export function styleBrief(p){const v=styleOf(p);return `Gaya ${v.name}. Format ${p.aspect}. ${v.rules}\nArahan tambahan: ${p.styleNotes||'ikuti gaya terpilih'}\nKarakter: ${p.characters?'boleh bila mendukung isi; konsisten':'tanpa manusia, wajah, atau stickman'}. Subtitle ${p.subtitle?'ditangani engine':'dimatikan'}. Durasi mengikuti VO. Kontinuitas visual dan loop akhir ke awal dirancang sesuai narasi. Aturan gaya tidak boleh mengubah naskah final.`;}
